class l{constructor(s,t,i){this.decay_=s,this.minVelocity_=t,this.delay_=i,this.points_=[],this.angle_=0,this.initialVelocity_=0}begin(){this.points_.length=0,this.angle_=0,this.initialVelocity_=0}update(s,t){this.points_.push(s,t,Date.now())}end(){if(this.points_.length<6)return!1;const s=Date.now()-this.delay_,t=this.points_.length-3;if(this.points_[t+2]<s)return!1;let i=t-3;for(;i>0&&this.points_[i+2]>s;)i-=3;const h=this.points_[t+2]-this.points_[i+2];if(h<1e3/60)return!1;const n=this.points_[t]-this.points_[i],e=this.points_[t+1]-this.points_[i+1];return this.angle_=Math.atan2(e,n),this.initialVelocity_=Math.sqrt(n*n+e*e)/h,this.initialVelocity_>this.minVelocity_}getDistance(){return(this.minVelocity_-this.initialVelocity_)/this.decay_}getAngle(){return this.angle_}}export default l;
